package e.e.a;
import java.text.*;
public class SearchDatePresetTest {
 static void check(String want,String actual){if(!want.equals(actual))throw new AssertionError(actual+" != "+want);}
 static long now(String text)throws Exception{return new SimpleDateFormat("yyyy-MM-dd HH:mm:ssZ").parse(text).getTime();}
 static void range(int mode,String date,String first,String last)throws Exception{long[] r=SearchRange.preset(mode,now(date));check(first,SearchRange.date(r[0]));check(last,SearchRange.date(r[1]));}
 public static void main(String[] args)throws Exception{String n="2026-10-13 00:12:00+0900";range(0,n,"2026-10-13","2026-10-13");range(1,n,"2026-10-06","2026-10-13");range(2,n,"2026-09-13","2026-10-13");range(3,n,"2025-10-13","2026-10-13");range(2,"2026-03-31 21:00:00+0900","2026-02-28","2026-03-31");range(3,"2024-02-29 21:00:00+0900","2023-02-28","2024-02-29");long stale=now("2025-12-28 00:00:00+0900"),current=now("2026-10-13 11:09:06+0900");for(int selected:new int[]{0,1,2,7}){long[] defaults=SearchRange.initialDates(selected,stale,stale,current);check("2026-10-13",SearchRange.date(defaults[0]));check("2026-10-13",SearchRange.date(defaults[1]));}long[] custom=SearchRange.initialDates(8,stale,stale,current);check("2025-12-28",SearchRange.date(custom[0]));check("2025-12-28",SearchRange.date(custom[1]));long[] tomorrow=SearchRange.initialDates(0,stale,stale,now("2026-10-13 15:00:00+0000"));check("2026-10-14",SearchRange.date(tomorrow[0]));check("2026-10-14",SearchRange.date(tomorrow[1]));System.out.println("Current-date search presets and dialog initialization: 24 date boundary/default/retention checks passed");}
}
